import React, { useState } from "react";

export default function App() {
  const [disease, setDisease] = useState("");
  const [focus, setFocus] = useState("");
  const [location, setLocation] = useState("");
  const [age, setAge] = useState("");
  const [gender, setGender] = useState("");
  const [whatIf, setWhatIf] = useState("");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);

  const [showPapers, setShowPapers] = useState(true);
  const [showTrials, setShowTrials] = useState(true);
  const [showRisk, setShowRisk] = useState(true);

  const handleRun = async () => {
    setLoading(true);
    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          disease,
          intent: focus,
          location,
          age,
          gender,
          what_if: whatIf,
        }),
      });
      const data = await res.json();
      setSummary(data.summary || "");
      setPublications(data.publications || []);
      setTrials(data.clinical_trials || []);
    } catch (e) {
      console.error(e);
    }
    setLoading(false);
  };

  return (
    <div style={{ display: "flex", height: "100vh", background: "#0B1220", color: "#E5E7EB" }}>

      {/* LEFT SIDEBAR */}
      <aside style={{ width: 300, borderRight: "1px solid #1F2937", padding: 16 }}>
        <h2 style={{ fontWeight: 700, marginBottom: 12 }}>Curalink X</h2>
        <p style={{ fontSize: 12, opacity: 0.7, marginBottom: 16 }}>AI Medical Research Copilot</p>

        <div style={{ marginBottom: 16 }}>
          <label style={{ fontSize: 12, opacity: 0.7 }}>Filter by disease</label>
          <input
            value={disease}
            onChange={(e) => setDisease(e.target.value)}
            placeholder="e.g., Parkinson's disease"
            style={styles.input}
          />
        </div>

        <div style={styles.card}>
          <div style={styles.cardTitle}>Insight Filters</div>
          <label style={styles.checkbox}><input type="checkbox" checked={showPapers} onChange={()=>setShowPapers(!showPapers)} /> Publications</label>
          <label style={styles.checkbox}><input type="checkbox" checked={showTrials} onChange={()=>setShowTrials(!showTrials)} /> Clinical trials</label>
          <label style={styles.checkbox}><input type="checkbox" checked={showRisk} onChange={()=>setShowRisk(!showRisk)} /> Risk analysis</label>
        </div>

        <div style={styles.card}>
          <div style={styles.cardTitle}>Stats</div>
          <Stat label="Research papers" value={publications.length} />
          <Stat label="Clinical trials" value={trials.length} />
          <Stat label="Risk confidence" value={summary ? "72%" : "0%"} />
          <Stat label="Pipeline time" value={loading ? "..." : "~250 ms"} />
        </div>
      </aside>

      {/* CENTER PANEL */}
      <main style={{ flex: 1, padding: 20, overflowY: "auto" }}>
        <h1 style={{ textAlign: "center", marginBottom: 16 }}>OpenAI reasoning copilot</h1>

        <div style={styles.card}>
          <textarea
            rows={3}
            placeholder="Ask your medical research question..."
            style={styles.textarea}
            onChange={(e)=>setFocus(e.target.value)}
          />

          <button onClick={handleRun} style={styles.button}>Send message</button>
        </div>

        <div style={styles.card}>
          <div style={styles.cardTitle}>Structured query metadata</div>
          <div style={styles.grid}>
            <input placeholder="Disease" value={disease} onChange={(e)=>setDisease(e.target.value)} style={styles.input} />
            <input placeholder="Research focus" value={focus} onChange={(e)=>setFocus(e.target.value)} style={styles.input} />
            <input placeholder="Location" value={location} onChange={(e)=>setLocation(e.target.value)} style={styles.input} />
            <input placeholder="Age" value={age} onChange={(e)=>setAge(e.target.value)} style={styles.input} />
            <input placeholder="Gender" value={gender} onChange={(e)=>setGender(e.target.value)} style={styles.input} />
            <input placeholder="What-if treatment" value={whatIf} onChange={(e)=>setWhatIf(e.target.value)} style={styles.input} />
          </div>
        </div>

        {loading && <p>⏳ Running pipeline...</p>}
      </main>

      {/* RIGHT PANEL */}
      <aside style={{ width: 380, borderLeft: "1px solid #1F2937", padding: 16, overflowY: "auto" }}>

        <div style={styles.card}>
          <div style={styles.cardTitle}>Dynamic Insights</div>
          <p style={{ fontSize: 12, opacity: 0.7 }}>Live synthesis</p>
        </div>

        {summary && (
          <div style={styles.card}>
            <div style={styles.cardTitle}>AI Summary</div>
            <p style={{ fontSize: 13 }}>{summary}</p>
          </div>
        )}

        {showPapers && (
          <div style={styles.card}>
            <div style={styles.cardTitle}>Research papers</div>
            {publications.length === 0 && <Empty text="No publication cards available yet." />}
            {publications.slice(0,5).map((p,i)=> (
              <div key={i} style={styles.item}>
                <div style={{ fontWeight: 600 }}>{p.title}</div>
                <div style={styles.meta}>{p.source} • {p.year}</div>
              </div>
            ))}
          </div>
        )}

        {showTrials && (
          <div style={styles.card}>
            <div style={styles.cardTitle}>Clinical trials</div>
            {trials.length === 0 && <Empty text="No clinical trials matched the current filters." />}
            {trials.slice(0,5).map((t,i)=> (
              <div key={i} style={styles.item}>
                <div style={{ fontWeight: 600 }}>{t.title}</div>
                <div style={styles.meta}>{t.status}</div>
              </div>
            ))}
          </div>
        )}

        {showRisk && (
          <div style={styles.card}>
            <div style={styles.cardTitle}>Risk analysis</div>
            {summary ? (
              <>
                <div style={{ marginBottom: 8 }}>Predicted impact: Moderate</div>
                <div style={{ fontSize: 12, opacity: 0.7 }}>Caution notes will appear here.</div>
              </>
            ) : (
              <Empty text="Risk analysis will appear after the first evidence run." />
            )}
          </div>
        )}

        <div style={styles.card}>
          <div style={styles.cardTitle}>What-if Analysis</div>
          <input value={whatIf} onChange={(e)=>setWhatIf(e.target.value)} placeholder="e.g., Vitamin D" style={styles.input} />
          <button onClick={handleRun} style={styles.button}>Simulate scenario</button>
        </div>

      </aside>
    </div>
  );
}

function Stat({ label, value }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6, fontSize: 13 }}>
      <span style={{ opacity: 0.7 }}>{label}</span>
      <strong>{value}</strong>
    </div>
  );
}

function Empty({ text }) {
  return <div style={{ fontSize: 12, opacity: 0.6 }}>{text}</div>;
}

const styles = {
  card: { background: "#111827", border: "1px solid #1F2937", borderRadius: 12, padding: 12, marginBottom: 12 },
  cardTitle: { fontWeight: 700, marginBottom: 8 },
  input: { width: "100%", padding: 8, borderRadius: 8, border: "1px solid #1F2937", background: "#0B1220", color: "#E5E7EB", marginTop: 6 },
  textarea: { width: "100%", padding: 10, borderRadius: 10, border: "1px solid #1F2937", background: "#0B1220", color: "#E5E7EB", marginBottom: 10 },
  button: { width: "100%", padding: 10, borderRadius: 10, border: "none", background: "linear-gradient(90deg,#3B82F6,#8B5CF6)", color: "white", cursor: "pointer" },
  grid: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 },
  checkbox: { display: "block", marginBottom: 6, fontSize: 13 },
  item: { borderTop: "1px solid #1F2937", paddingTop: 8, marginTop: 8 },
  meta: { fontSize: 12, opacity: 0.7 }
};
